package com.mo.economy_system.common.territory;
import static org.junit.jupiter.api.Assertions.*;import java.util.*;import org.junit.jupiter.api.Test;
class TerritoryInviteRequestServiceTest{@Test void validatesAndCreatesServerIdentity(){UUID owner=UUID.randomUUID(),target=UUID.randomUUID(),territory=UUID.randomUUID(),inviteId=UUID.randomUUID();TerritoryInviteRequestService s=new TerritoryInviteRequestService(id->Optional.of(new TerritoryInviteRequestService.Territory(territory,owner,"land",Set.of())),id->id.equals(target)?Optional.of(new TerritoryInviteRequestService.Player(target,"target")):Optional.empty(),new TerritoryInviteStore(),new TerritoryInviteRateLimiter(),()->inviteId);var o=s.create(owner,"owner",territory,target,10);assertEquals(TerritoryInviteResult.SUCCESS,o.result());assertEquals(inviteId,o.invite().inviteId());assertEquals(target,o.invite().targetPlayerId());assertEquals(1210,o.invite().expiresTick());assertEquals(TerritoryInviteResult.ALREADY_PENDING,s.create(owner,"owner",territory,target,50).result());}@Test void doesNotSwallowErrors(){UUID u=UUID.randomUUID();TerritoryInviteRequestService s=new TerritoryInviteRequestService(id->{throw new AssertionError();},id->Optional.empty(),new TerritoryInviteStore(),new TerritoryInviteRateLimiter(),UUID::randomUUID);assertThrows(AssertionError.class,()->s.create(u,"x",u,UUID.randomUUID(),0));}}
